# Hymns not in the 1954 library, typed from the 1909 OCR (Latin) with an AI translation.
def _hy(stanzas):
    out = []
    for i, s in enumerate(stanzas):
        ls = s.split(' / '); f = ls[0]
        out.append(('<c>%s</c>' if i == 0 else '<h>%s</h>') % f[0] + '\n'.join([f[1:]] + ls[1:]))
    return '\n\n'.join(out)
